import{_ as l,a0 as o,w as t,s as r,I as a,x as n,a1 as p,A as i,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"Odoo 提速指南 | LCTT x X-CMD","titleTemplate":false,"description":"Odoo 提速指南 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Odoo 提速指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Odoo 提速指南 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170113 How to Speed up Odoo copy","title":"Odoo 提速指南","tag":"201703","desc":""},"relativePath":"201703/20170113 How to Speed up Odoo copy.md","filePath":"[post].md"}'),u={name:"201703/20170113 How to Speed up Odoo copy.md"};function g(h,s,m,f,k,b){const e=o("Link");return t(),r("div",null,[s[25]||(s[25]=a("h1",{id:"odoo-提速指南",tabindex:"-1"},[n("Odoo 提速指南 "),a("a",{class:"header-anchor",href:"#odoo-提速指南","aria-label":"Permalink to “Odoo 提速指南”"},"​")],-1)),s[26]||(s[26]=a("p",null,[a("img",{src:"https://www.rosehosting.com/blog/wp-content/uploads/2016/12/speed-up-odoo.jpg",alt:"speed up odoo"})],-1)),s[27]||(s[27]=a("p",null,"Odoo 是最流行的 ERP（企业资源计划）软件，它由 Python 编写，使用 PostgreSQL 作为后端数据库。Odoo 社区版是免费的开源软件，它囊括了项目管理，生产、财务、记账和销售管理，仓储管理，人力资源管理，甚至还有更多项目。里面包含了 30 个核心模块，以及超过 3000 个社区模块。Odoo 部署了大量的模块，数据库里也包含了庞大的数据等等，这些都使得这个软件比较复杂，可能会导致效率低下。Odoo 的两个主要瓶颈在于磁盘访问，以及数据库查询时间。",-1)),s[28]||(s[28]=a("p",null,"为了提升 Odoo 实例的性能，你可以：",-1)),a("ul",null,[s[3]||(s[3]=a("li",null,"使用一个快速磁盘驱动器来存储（最好是 SSD）。",-1)),a("li",null,[s[1]||(s[1]=n("使用",-1)),p(e,{href:"https://www.rosehosting.com/linux-vps-hosting.html"},{default:i(()=>[...s[0]||(s[0]=[n("内存充足的 Linux VPS",-1)])]),_:1}),s[2]||(s[2]=n("。",-1))]),s[4]||(s[4]=a("li",null,[n("在 Odoo 中激活"),a("ruby",null,[n("多处理器模式"),a("rt",null,"multiprocessing mode")]),n("。")],-1)),s[5]||(s[5]=a("li",null,"正确配置并优化 PostgreSQL 服务。",-1))]),s[29]||(s[29]=a("h3",{id:"获得一台有着更多内存的-ssd-vps",tabindex:"-1"},[n("获得一台有着更多内存的 SSD VPS "),a("a",{class:"header-anchor",href:"#获得一台有着更多内存的-ssd-vps","aria-label":"Permalink to “获得一台有着更多内存的 SSD VPS”"},"​")],-1)),a("p",null,[s[7]||(s[7]=n("正如我们先前提到的，随机磁盘访问速度是 Odoo 的主要瓶颈之一。因此，要确保 Odoo 部署在一台",-1)),p(e,{href:"https://www.rosehosting.com/linux-vps-hosting.html"},{default:i(()=>[...s[6]||(s[6]=[n("基于 SSD 的 VPS",-1)])]),_:1}),s[8]||(s[8]=n(" 上。由于 Odoo 是一个对资源十分敏感的应用，因此始终要把它安装在一台有着更多 RAM 的 VPS 上，如果可能，将整个 Odoo 实例及其数据库加载到 RAM 中。固态磁盘驱动器尤其以随机存取见长，而且由于 SSD 没有任何活动部件，它们能够取得数百倍于传统机械硬盘驱动器的随机存取 IOPS（LCTT译注：即每秒读写操作的次数）。如果服务器没有采用 SSD 来驱动或提速，那么不管你对 Odoo 做多少优化和配置都无济于事，它仍然会很慢。所以，获得正确的主机来部署 Odoo 是提升其性能的最重要因素。",-1))]),s[30]||(s[30]=d(`<p>其它 Odoo 优化包括：</p><h3 id="在-odoo-配置中启用多处理器选项" tabindex="-1">在 Odoo 配置中启用多处理器选项 <a class="header-anchor" href="#在-odoo-配置中启用多处理器选项" aria-label="Permalink to “在 Odoo 配置中启用多处理器选项”">​</a></h3><p>要实现此功能，请定位到 openerp 服务器二进制文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#updatedb</span></span>
<span class="line"><span>#locate openerp-server</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/usr/bin/openerp-server</span></span></code></pre></div><p>执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#/usr/bin/openerp-server --help</span></span></code></pre></div><p>该命令的输出结果如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Usage: openerp-server [options]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  --version             show program&#39;s version number and exit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  (...)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Multiprocessing options:</span></span>
<span class="line"><span>    --workers=WORKERS   Specify the number of workers, 0 disable prefork mode.</span></span>
<span class="line"><span>    --limit-memory-soft=LIMIT_MEMORY_SOFT</span></span>
<span class="line"><span>                        Maximum allowed virtual memory per worker, when</span></span>
<span class="line"><span>                        reached the worker be reset after the current request</span></span>
<span class="line"><span>                        (default 671088640 aka 640MB).</span></span>
<span class="line"><span>    --limit-memory-hard=LIMIT_MEMORY_HARD</span></span>
<span class="line"><span>                        Maximum allowed virtual memory per worker, when</span></span>
<span class="line"><span>                        reached, any memory allocation will fail (default</span></span>
<span class="line"><span>                        805306368 aka 768MB).</span></span>
<span class="line"><span>    --limit-time-cpu=LIMIT_TIME_CPU</span></span>
<span class="line"><span>                        Maximum allowed CPU time per request (default 60).</span></span>
<span class="line"><span>    --limit-time-real=LIMIT_TIME_REAL</span></span>
<span class="line"><span>                        Maximum allowed Real time per request (default 120).</span></span>
<span class="line"><span>    --limit-request=LIMIT_REQUEST</span></span>
<span class="line"><span>                        Maximum number of request to be processed per worker</span></span>
<span class="line"><span>                        (default 8192).</span></span></code></pre></div><p>工作进程的数量应该和分配到 VPS 的 CPU 核心数一样，或者，如果你想为 PostgreSQL 数据库、cron 任务、或者其它和 Odoo 实例安装在同一台 VPS 上的其它应用预留出一些 CPU 核心，那么你可以将工作进程数设置为一个比 VPS 上可用 CPU 核心更低的值，以避免资源耗尽。</p><p>limit-memory-soft 和 limit-memory-hard 参数不言自明，你可以使用默认值，也可以根据 VPS 上的实际可用 RAM 来进行修改。</p><p>例如，如果你的 VPS 有 8 个 CPU 核心，以及 16 GB 内存，那么你可以将工作进程数设置为 17（CPU 核心数 x 2 + 1），limit-memory-soft 总值设置为 640 x 17 = 10880 MB，而 limit-memory-hard 总数设置为 68MB x 17 = 13056 MB，这样，Odoo 就会有总计达 12.75 GB 的 RAM。</p><p>例如，在一台拥有 16 GB RAM 和 8 个 CPU 核心的 VPS 上，编辑 Odoo 配置文件（如 /etc/odoo-server.conf），并添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /etc/odoo-server.conf</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>workers = 17</span></span>
<span class="line"><span></span></span>
<span class="line"><span>limit_memory_hard = 805306368</span></span>
<span class="line"><span></span></span>
<span class="line"><span>limit_memory_soft = 671088640</span></span>
<span class="line"><span></span></span>
<span class="line"><span>limit_request = 8192</span></span>
<span class="line"><span></span></span>
<span class="line"><span>limit_time_cpu = 60</span></span>
<span class="line"><span></span></span>
<span class="line"><span>limit_time_real = 120</span></span>
<span class="line"><span></span></span>
<span class="line"><span>max_cron_threads = 2</span></span></code></pre></div><p>别忘了重启 Odoo 让修改生效。</p><h3 id="正确配置并优化-postgresql" tabindex="-1">正确配置并优化 PostgreSQL <a class="header-anchor" href="#正确配置并优化-postgresql" aria-label="Permalink to “正确配置并优化 PostgreSQL”">​</a></h3><p>对于 PostgreSQL 优化，及时将它更新到最新版本是一个不错的主意。在 PostgreSQL 配置文件（pg_hba.conf）中，有两个设置需要修改：shared_buffers 和 effective_cache_size。将 shared_buffers 设置为可用内存的 20%，effective_cache_size 设置为可用内存的 50%。</p><p>例如，如果 Odoo 安装到了一台 16 GB RAM 的 SSD VPS 上，那么在 pg_hba.conf 中使用如下设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi /var/lib/postgresql/data/pg_hba.conf</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shared_buffers = 3072MB</span></span>
<span class="line"><span>effective_cache_size = 8192MB</span></span></code></pre></div><p>重启 PostgreSQL 服务来让修改生效。</p>`,21)),a("p",null,[s[10]||(s[10]=n("同时，也别忘了周期性手动执行 ‘",-1)),a("strong",null,[p(e,{href:"https://wiki.postgresql.org/wiki/Introduction_to_VACUUM,_ANALYZE,_EXPLAIN,_and_COUNT"},{default:i(()=>[...s[9]||(s[9]=[n("VACUUM",-1)])]),_:1})]),s[11]||(s[11]=n("’。此操作会将陈旧或临时数据清理干净，但请牢记，它会大量占用 CPU 和磁盘使用。",-1))]),s[31]||(s[31]=a("hr",null,null,-1)),a("p",null,[s[13]||(s[13]=n("via: ",-1)),p(e,{href:"https://www.rosehosting.com/blog/how-to-speed-up-odoo/"},{default:i(()=>[...s[12]||(s[12]=[n("https://www.rosehosting.com/blog/how-to-speed-up-odoo/",-1)])]),_:1})]),a("p",null,[s[17]||(s[17]=n("作者：",-1)),p(e,{href:"https://www.rosehosting.com/"},{default:i(()=>[...s[14]||(s[14]=[n("rosehosting.com",-1)])]),_:1}),s[18]||(s[18]=n(" 译者：",-1)),p(e,{href:"https://github.com/GOLinux"},{default:i(()=>[...s[15]||(s[15]=[n("GOLinux",-1)])]),_:1}),s[19]||(s[19]=n(" 校对：",-1)),p(e,{href:"https://github.com/jasminepeng"},{default:i(()=>[...s[16]||(s[16]=[n("jasminepeng",-1)])]),_:1})]),a("p",null,[s[22]||(s[22]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[20]||(s[20]=[n("LCTT",-1)])]),_:1}),s[23]||(s[23]=n(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...s[21]||(s[21]=[n("Linux中国",-1)])]),_:1}),s[24]||(s[24]=n(" 荣誉推出",-1))])])}const C=l(u,[["render",g]]);export{w as __pageData,C as default};
